24	constexpr uint16_t kDecoderListenPort = 26001;
25	constexpr uint16_t kPromptListenPort = 26000;
26	constexpr uint16_t kDecoderControlPort = 26003;
27	constexpr uint16_t kPromptClusterId = 0;
28	constexpr uint32_t kNumTensors = 4U;
29	constexpr size_t kTensorSize = 8 * 16 * sizeof(int32_t);
30	const std::vector<int64_t> kTensorShape = {8, 16};
31	constexpr int32_t kWaitTime = 5;
