44	#define CHECK_ACL(x)                                                                  \
45	  do {                                                                                \
46	    aclError __ret = x;                                                               \
47	    if (__ret != ACL_ERROR_NONE) {                                                    \
48	      std::cerr << __FILE__ << ":" << __LINE__ << " aclError:" << __ret << std::endl; \
