67	int Initialize(LlmDataDist &llm_datadist, const std::string &device_id, const std::string &local_ip,
68	               const std::string &transfer_backend, const std::string &local_comm_res) {
69	  std::map<AscendString, AscendString> options;
70	  options[OPTION_DEVICE_ID] = device_id.c_str();
71	  options[OPTION_LISTEN_IP_INFO] = (local_ip + ":" + std::to_string(kPromptListenPort)).c_str();
72	  if (!transfer_backend.empty()) {
73	    if (transfer_backend != "hixl") {
74	      printf("[ERROR] unsupported transfer_backend: %s\n", transfer_backend.c_str());
75	      return -1;
76	    }
77	    options[OPTION_TRANSFER_BACKEND] = "hixl";
78	  }
79	  if (!local_comm_res.empty()) {
80	    options[OPTION_LOCAL_COMM_RES] = local_comm_res.c_str();
81	  }
82	  auto ret = llm_datadist.Initialize(options);
83	  if (ret != LLM_SUCCESS) {
84	    printf("[ERROR] Initialize failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
85	    return -1;
86	  }
87	  printf("[INFO] Initialize success\n");
88	  return LLM_SUCCESS;
89	}
90	
91	int Link(LlmDataDist &llm_datadist, const char *local_ip, const char *remote_ip) {
92	  std::vector<Status> rets;
93	  std::vector<ClusterInfo> clusters;
94	  ClusterInfo cluster_info;
95	  cluster_info.remote_cluster_id = 1;
96	  IpInfo local_ip_info;
97	  local_ip_info.ip = local_ip;
98	  local_ip_info.port = kPromptListenPort;
99	  cluster_info.local_ip_infos.emplace_back(std::move(local_ip_info));
100	  IpInfo remote_ip_info;
101	  remote_ip_info.ip = remote_ip;
102	  remote_ip_info.port = kDecoderListenPort;
103	  cluster_info.remote_ip_infos.emplace_back(std::move(remote_ip_info));
104	  clusters.emplace_back(std::move(cluster_info));
105	  auto ret = llm_datadist.LinkLlmClusters(clusters, rets, 5000);
106	  if (ret != LLM_SUCCESS) {
107	    printf("[ERROR] LinkLlmClusters failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
108	    return -1;
109	  }
110	  printf("[INFO] LinkLlmClusters success\n");
111	  return 0;
112	}
