114	int Unlink(LlmDataDist &llm_datadist, const char *remote_ip) {
115	  std::vector<Status> rets;
116	  std::vector<ClusterInfo> clusters;
117	  ClusterInfo cluster_info;
118	  cluster_info.remote_cluster_id = 1;
119	  IpInfo remote_ip_info;
120	  remote_ip_info.ip = remote_ip;
121	  remote_ip_info.port = kDecoderListenPort;
122	  cluster_info.remote_ip_infos.emplace_back(std::move(remote_ip_info));
123	  clusters.emplace_back(std::move(cluster_info));
124	  auto ret = llm_datadist.UnlinkLlmClusters(clusters, rets, 5000);
125	  if (ret != LLM_SUCCESS) {
126	    printf("[ERROR] UnlinkLlmClusters failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
127	    return -1;
128	  }
129	  printf("[INFO] UnlinkLlmClusters success\n");
130	  return 0;
131	}
