167	    CHECK_ACL(aclrtMemcpy(&host_buffer[0], kTensorSize, buffer, kTensorSize, ACL_MEMCPY_DEVICE_TO_HOST));
168	    for (auto check_index : check_index_list) {
169	      for (size_t i = 0U; i < kTensorBlockElementNum; ++i) {
170	        auto expect = check_index * kTensorBlockElementNum + i;
171	        if (static_cast<uint32_t>(host_buffer[expect]) != expect) {
172	          printf("[ERROR] Buffer check failed, index = %zu, val = %d, expect val = %zu\n", expect, host_buffer[expect],
173	                 expect);
