261	int32_t RunDecoderSample(const char *device_id, const char *local_ip, const char *remote_ip,
262	                         const std::string &transfer_backend, const std::string &local_comm_res) {
263	  printf("[INFO] Decoder Sample start\n");
264	  // 1. 初始化
265	  LlmDataDist llm_datadist(kDecoderClusterId, LlmRole::kDecoder);
266	  if (Initialize(llm_datadist, device_id, local_ip, transfer_backend, local_comm_res) != 0) {
267	    return -1;
268	  }
269	
270	  // 2. 注册内存地址
271	  std::vector<void *> buffers;
272	  int64_t cache_id = -1;
273	  bool linked = false;
274	  if (RegisterCache(llm_datadist, buffers, cache_id) != 0) {
275	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
276	    return -1;
277	  }
278	
279	  // 3. 等待prompt写完cache，实际业务场景可通过合适方式实现通知
280	  std::this_thread::sleep_for(std::chrono::seconds(kWaitPromptTime));
281	
282	  // 4. 与prompt建链
283	  if (Link(llm_datadist, local_ip, remote_ip) != 0) {
284	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
285	    return -1;
286	  }
287	  linked = true;
288	
289	  // 5. 从prompt拉取cache
290	  if (PullCache(llm_datadist, cache_id) != 0) {
291	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
292	    return -1;
293	  }
294	
295	  if (CheckBuffers(buffers, {0, 1, 2, 3}) != 0) {
296	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
297	    return -1;
298	  }
299	
300	  // 6. 解除链路
301	  if (Unlink(llm_datadist, remote_ip) != 0) {
302	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
303	    return -1;
304	  }
305	  linked = false;
306	  if (NotifyUnlinkDone(remote_ip, kPromptControlPort) != 0) {
307	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
308	    return -1;
309	  }
310	
311	  // 7. 释放cache与llmDataDist
312	  llm_datadist.Finalize();
313	  printf("[INFO] Decoder Sample end\n");
314	  return 0;
315	}
