318	  if (argc < kExpectedArgCnt - 2 || argc > kExpectedArgCnt) {
319	    printf(
320	        "[ERROR] expect args(device_id, localHostIp, remoteHostIp, [transfer_backend], [local_comm_res]), "
321	        "but got %d\n",
322	        argc - 1);
323	    return -1;
324	  }
325	  const auto device_id = argv[kArgIndexDeviceId];
326	  const auto local_ip = argv[kArgIndexLocalIp];
327	  const auto remote_ip = argv[kArgIndexRemoteIp];
328	  printf("[INFO] device_id = %s, local_ip = %s, remote_ip = %s\n", device_id, local_ip, remote_ip);
329	  std::string transfer_backend;
330	  std::string local_comm_res;
331	  if (argc > kArgIndexTransferBackend) {
332	    transfer_backend = argv[kArgIndexTransferBackend];
333	    printf("[INFO] transfer_backend = %s\n", transfer_backend.c_str());
334	  }
335	  if (argc > kArgIndexLocalCommRes) {
336	    local_comm_res = argv[kArgIndexLocalCommRes];
337	    printf("[INFO] local_comm_res = %s\n", local_comm_res.c_str());
